import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Shared memory tile for B: KTILE(32) x BLOCK_X(16) = 2048 bytes
.shared .align 4 .b8 sB[2048];
.visible .entry matmul_kernel(
    .param .u64 param_A_ptr,
    .param .u64 param_B_ptr,
    .param .u64 param_C_ptr,
    .param .u32 param_M,
    .param .u32 param_N,
    .param .u32 param_K
)
{
    .reg .pred  %p_exit, %p0, %p1, %p_done, %p_phase_done, %p_skip, %p_il_done, %p_lt;
    .reg .u32   %r_row, %r_col, %r_M, %r_N, %r_K;
    .reg .u32   %r_tid_x, %r_tid_y, %r_blk_x, %r_blk_y, %r_ntid_x, %r_ntid_y;
    .reg .u32   %r_kt, %r_tileK, %r_rem, %r_base, %r_kk, %r_gk, %r_k2, %r_gk2;
    .reg .u64   %A, %B, %C;
    .reg .u64   %a_rowK64, %a_idx64, %offA;
    .reg .u64   %b_kN64, %b_idx64, %offB;
    .reg .u64   %col64, %c_rowN64, %c_idx64, %offC;
    .reg .u64   %sbase, %s_addr, %s_off, %tmp64, %tidx64, %s_idx64;
    .reg .u64   %tmp64b, %tx64, %s_idx64b, %s_offb, %sbase2, %s_addr2;
    .reg .f32   %fa, %fb, %fb2, %acc;
    // Load parameters
    ld.param.u64 %A, [param_A_ptr];
    ld.param.u64 %B, [param_B_ptr];
    ld.param.u64 %C, [param_C_ptr];
    ld.param.u32 %r_M, [param_M];
    ld.param.u32 %r_N, [param_N];
    ld.param.u32 %r_K, [param_K];
    // Compute global row, col
    mov.u32 %r_tid_x, %tid.x;
    mov.u32 %r_tid_y, %tid.y;
    mov.u32 %r_blk_x, %ctaid.x;
    mov.u32 %r_blk_y, %ctaid.y;
    mov.u32 %r_ntid_x, %ntid.x;
    mov.u32 %r_ntid_y, %ntid.y;
    mad.lo.s32 %r_col, %r_blk_x, %r_ntid_x, %r_tid_x;
    mad.lo.s32 %r_row, %r_blk_y, %r_ntid_y, %r_tid_y;
    // Bounds check: if row >= M or col >= N => exit
    setp.ge.u32 %p0, %r_row, %r_M;
    setp.ge.u32 %p1, %r_col, %r_N;
    or.pred %p_exit, %p0, %p1;
    @%p_exit bra DONE;
    // Precompute 64-bit column index
    cvt.u64.u32 %col64, %r_col;
    // Initialize accumulator and tile counter
    mov.f32 %acc, 0f00000000; // 0.0f
    mov.u32 %r_kt, 0;
TILE_LOOP:
    setp.ge.u32 %p_done, %r_kt, %r_K;
    @%p_done bra STORE;
    // tileK = min(32, K - kt)
    sub.s32 %r_rem, %r_K, %r_kt;
    mov.u32 %r_tileK, 32;
    setp.lt.u32 %p_lt, %r_rem, %r_tileK;
    @%p_lt mov.u32 %r_tileK, %r_rem;
    // Cooperative load of B tile into shared memory in phases of 16 along K
    mov.u32 %r_base, 0;
PHASE_LOOP:
    setp.ge.u32 %p_phase_done, %r_base, %r_tileK;
    @%p_phase_done bra PHASE_END;
    add.u32 %r_kk, %r_base, %r_tid_y;        // kk = base + tid.y
    setp.ge.u32 %p_skip, %r_kk, %r_tileK;    // if kk >= tileK skip load
    @%p_skip bra SKIP_LOAD;
    // Global k index for this phase element
    add.u32 %r_gk, %r_kt, %r_kk;
    // B index: gk * N + col
    mul.wide.u32 %b_kN64, %r_gk, %r_N;
    add.u64 %b_idx64, %b_kN64, %col64;
    shl.b64 %offB, %b_idx64, 2;         // *4 bytes
    add.u64 %offB, %offB, %B;
    ld.global.f32 %fb, [%offB];
    // Store B to shared: index = kk * 16 + tid.x
    mul.wide.u32 %tmp64, %r_kk, 16;
    cvt.u64.u32 %tidx64, %r_tid_x;
    add.u64 %s_idx64, %tmp64, %tidx64;
    shl.b64 %s_off, %s_idx64, 2;
     mov.u64 %sbase, sB;
    add.u64 %s_addr, %sbase, %s_off;
    st.shared.f32 [%s_addr], %fb;
SKIP_LOAD:
    add.u32 %r_base, %r_base, 16;
    bra PHASE_LOOP;
PHASE_END:
    bar.sync 0;
    // Accumulate over the tileK from shared B
    mov.u32 %r_k2, 0;
INNER_LOOP:
    setp.ge.u32 %p_il_done, %r_k2, %r_tileK;
    @%p_il_done bra AFTER_INNER;
    // Load A[row, kt + k2]
    add.u32 %r_gk2, %r_kt, %r_k2;
    mul.wide.u32 %a_rowK64, %r_row, %r_K;
    cvt.u64.u32 %a_idx64, %r_gk2;
    add.u64 %a_idx64, %a_rowK64, %a_idx64;
    shl.b64 %offA, %a_idx64, 2;
    add.u64 %offA, %offA, %A;
    ld.global.f32 %fa, [%offA];
    // Load B from shared: sB[k2 * 16 + tid.x]
    mul.wide.u32 %tmp64b, %r_k2, 16;
    cvt.u64.u32 %tx64, %r_tid_x;
    add.u64 %s_idx64b, %tmp64b, %tx64;
    shl.b64 %s_offb, %s_idx64b, 2;
     mov.u64 %sbase2, sB;
    add.u64 %s_addr2, %sbase2, %s_offb;
    ld.shared.f32 %fb2, [%s_addr2];
    fma.rn.f32 %acc, %fa, %fb2, %acc;
    add.u32 %r_k2, %r_k2, 1;
    bra INNER_LOOP;
AFTER_INNER:
    bar.sync 0;
    add.u32 %r_kt, %r_kt, %r_tileK;
    bra TILE_LOOP;
STORE:
    // C index: row * N + col
    mul.wide.u32 %c_rowN64, %r_row, %r_N;
    add.u64 %c_idx64, %c_rowN64, %col64;
    shl.b64 %offC, %c_idx64, 2;         // *4 bytes
    add.u64 %offC, %offC, %C;
    st.global.f32 [%offC], %acc;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        # Validate inputs
        assert A.device.type == "cuda" and B.device.type == "cuda", "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 is supported"
        assert A.is_contiguous() and B.is_contiguous(), "Inputs must be contiguous"
        M, K = A.shape
        Kb, N = B.shape
        assert K == Kb, "Inner dimensions must match"
        C = torch.empty((M, N), device=A.device, dtype=A.dtype)

        # Launch parameters
        block_x, block_y, block_z = 16, 16, 1
        grid_x = (N + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y
        grid_z = 1

        module = _get_ptx_module()
        module.launch(
            "matmul_kernel",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[A, B, C, u32(M), u32(N), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

